/**
 * Recovery code and recovery blob.
 *
 * The user keeps a 100-bit code generated by the app. Two values are derived from it with
 * Argon2id, the derivation used everywhere else in the app:
 *  - a recovery ID, the lookup key the server indexes blobs by (not reversible to the code);
 *  - a blob key, which encrypts the account's secret key with XChaCha20-Poly1305.
 * The server stores only { ID -> encrypted blob }. Without the code it learns neither the
 * secret key nor which account the blob belongs to. No licence is involved.
 *
 * On mobile, the caller must inject a WebView-backed Argon2id (`kdf`). The JS implementation
 * must not run on the UI thread.
 */
import { argon2id } from "@noble/hashes/argon2.js";
import { bytesToHex, hexToBytes } from "@noble/hashes/utils.js";
import { randomBytes } from "@noble/ciphers/utils.js";
import { encryptVault, decryptVault } from "./crypto";
import type { EncryptedVault } from "./types";

export const RECOVERY_CODE_LENGTH = 20; // 20 x 5 bits = 100 bits
// Crockford base32: no I, L, O or U. Look-alikes are mapped on input.
const ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
// 24 bytes, so it can never equal a 16-byte blob salt: the two derivations are domain-separated.
const ID_SALT = new TextEncoder().encode("vaultkeepr-recovery-id-v1");
const SALT_LENGTH = 16;
// Same parameters as the rest of the app (hiddenWallet.ts, kdf-argon2.ts).
const ARGON2_OPTS = { t: 3, m: 65536, p: 4, dkLen: 32 };
const SECRET_KEY_HEX = /^[0-9a-fA-F]{64}$/;

/**
 * An account key is the standard 64-hex key, or any other text of 32 to 4096 characters, kept exactly as
 * given: the account identity is derived from the exact string. The extension's envelope shape {v, iv, ct}
 * and PGP armour are never account keys.
 */
export function isAccountKeyText(value: string): boolean {
  if (SECRET_KEY_HEX.test(value)) return true;
  if (value.length < 32 || value.length > 4096 || value.includes("BEGIN PGP")) return false;
  return !isEnvelopeText(value);
}

function isEnvelopeText(value: string): boolean {
  if (!value.startsWith("{")) return false;
  try {
    const o = JSON.parse(value) as { v?: unknown; iv?: unknown; ct?: unknown } | null;
    return !!o && typeof o === "object" && typeof o.v === "number" && typeof o.iv === "string" && typeof o.ct === "string";
  } catch {
    return false;
  }
}

/** Argon2id over the canonical code bytes. Mobile injects a WebView-backed implementation. */
export type RecoveryKdf = (codeBytes: Uint8Array, salt: Uint8Array) => Promise<Uint8Array> | Uint8Array;

export const argon2RecoveryKdf: RecoveryKdf = (codeBytes, salt) => argon2id(codeBytes, salt, ARGON2_OPTS);

export interface RecoveryBlob {
  version: 1;
  salt: string; // hex
  encrypted: EncryptedVault;
}

export function generateRecoveryCode(): string {
  const bytes = randomBytes(RECOVERY_CODE_LENGTH);
  let code = "";
  for (const b of bytes) code += ALPHABET[b % 32]; // 256 % 32 === 0: no modulo bias
  return code;
}

/** Canonical form: uppercase, no spaces or hyphens, O -> 0, I and L -> 1. */
export function normalizeRecoveryCode(input: string): string {
  return input
    .toUpperCase()
    .replace(/[\s-]/g, "")
    .replace(/O/g, "0")
    .replace(/[IL]/g, "1");
}

export function isValidRecoveryCode(input: string): boolean {
  const code = normalizeRecoveryCode(input);
  return code.length === RECOVERY_CODE_LENGTH && [...code].every((c) => ALPHABET.includes(c));
}

/** Display form, in groups of five: XXXXX-XXXXX-XXXXX-XXXXX. */
export function formatRecoveryCode(code: string): string {
  const canonical = normalizeRecoveryCode(code);
  return canonical.match(/.{1,5}/g)?.join("-") ?? canonical;
}

function codeBytes(code: string): Uint8Array {
  const canonical = normalizeRecoveryCode(code);
  if (!isValidRecoveryCode(canonical)) throw new Error("Invalid recovery code");
  return new TextEncoder().encode(canonical);
}

/** Lookup key for the server. Only someone holding the code can compute it. */
export async function deriveRecoveryId(code: string, kdf: RecoveryKdf = argon2RecoveryKdf): Promise<string> {
  return bytesToHex(await kdf(codeBytes(code), ID_SALT));
}

/** Encrypts the account's secret key under a key derived from the recovery code. */
export async function createRecoveryBlob(
  secretKeyHex: string,
  code: string,
  kdf: RecoveryKdf = argon2RecoveryKdf,
): Promise<RecoveryBlob> {
  if (!isAccountKeyText(secretKeyHex)) throw new Error("Invalid secret key");
  const salt = randomBytes(SALT_LENGTH);
  const key = await kdf(codeBytes(code), salt);
  const encrypted = encryptVault(secretKeyHex, key);
  return { version: 1, salt: bytesToHex(salt), encrypted };
}

/** Recovers the secret key. A wrong code and a damaged blob give the same error. */
export async function openRecoveryBlob(
  blob: RecoveryBlob,
  code: string,
  kdf: RecoveryKdf = argon2RecoveryKdf,
): Promise<string> {
  if (blob.version !== 1) throw new Error("Unsupported recovery blob version");
  let plain: string | Uint8Array;
  try {
    const key = await kdf(codeBytes(code), hexToBytes(blob.salt));
    plain = decryptVault(blob.encrypted, key);
  } catch {
    throw new Error("Recovery failed");
  }
  const secretKey = typeof plain === "string" ? plain : new TextDecoder().decode(plain);
  if (!isAccountKeyText(secretKey)) throw new Error("Recovery failed");
  return secretKey;
}
